import XCTest

class BlueskyUITest: XCTestCase {
    let app = XCUIApplication()

    func testOpenNotifications() {
        // First, dismiss any dialogs by pressing Escape or Cancel
        let cancelButton = app.dialogs.firstMatch.buttons["Cancel"]
        if cancelButton.exists {
            cancelButton.tap()
            sleep(1)
        }

        // Find and tap the bell icon in the tab bar
        let notificationsTabIcon = app.tabBars.buttons.matching(NSPredicate(format: "label CONTAINS 'Notifications'")).firstMatch
        if notificationsTabIcon.exists {
            notificationsTabIcon.tap()
        } else {
            // Try finding by position - bell should be the last icon
            let tabBar = app.tabBars.firstMatch
            let tabBarButtons = tabBar.buttons
            if tabBarButtons.count > 0 {
                let lastButton = tabBarButtons.element(boundBy: tabBarButtons.count - 1)
                lastButton.tap()
            }
        }

        sleep(1)
    }
}
